async function buildCandidate(a){const base=rev(a.baseId);const im=await imageOf(base.image),ma=await imageOf(a.mask),pr=await imageOf(a.protection);const w=state.width,h=state.height;const beforeC=createCanvas();beforeC.getContext('2d').drawImage(im,0,0,w,h);const before=beforeC.getContext('2d').getImageData(0,0,w,h);const rawC=createCanvas(),ctx=rawC.getContext('2d');ctx.drawImage(im,0,0,w,h);const [x0,y0,x1,y1]=a.stats.bbox;const roiW=x1-x0,roiH=y1-y0;let fill='#ecf3f5';if(a.variation%3===1)fill='#edf4f1';if(a.variation%3===2)fill='#eef2f6';ctx.fillStyle=fill;ctx.fillRect(x0,y0,roiW,roiH);ctx.strokeStyle='#386170';ctx.lineWidth=1.1;const targetSample=state.isSample&&a.effect!=='label'&&x0>=220&&x1<=383&&y0>=355&&y1<=477;
 if(a.effect==='racks'){let cols=3,rows=2;const pad=targetSample?12:Math.max(5,Math.min(roiW,roiH)*.08);const rackW=Math.min(24,(roiW-pad*2-(cols-1)*10)/cols),rackH=targetSample?28:Math.min(38,(roiH-pad*2-18)/2);if(rackW<4||rackH<5)throw new Error('选区过小，无法展示两排机柜。请扩大可编辑区域。');for(let r=0;r<rows;r++){for(let c=0;c<cols;c++){const xx=x0+pad+c*(roiW-pad*2-rackW)/(cols-1);const yy=targetSample?(r===0?374:440):y0+pad+r*(roiH-2*pad-rackH);ctx.fillStyle='#fbfdfc';ctx.fillRect(xx,yy,rackW,rackH);ctx.strokeRect(xx+.5,yy+.5,rackW,rackH);ctx.strokeStyle='#95adb4';ctx.lineWidth=.65;for(let j=5;j<rackH-3;j+=5){ctx.beginPath();ctx.moveTo(xx+3,yy+j);ctx.lineTo(xx+rackW-3,yy+j);ctx.stroke()}ctx.strokeStyle='#386170';ctx.lineWidth=1.1}}}
 if(a.effect==='label'){const fontSize=clamp(Math.floor(roiW/7.4),7,16);ctx.fillStyle='#15324a';ctx.font=`${fontSize}px "PingFang SC","Microsoft YaHei","Noto Sans CJK SC",sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('运行办公室',(x0+x1)/2,(y0+y1)/2,Math.max(5,roiW-4))}
 const raw=ctx.getImageData(0,0,w,h);const maskC=createCanvas(),pC=createCanvas();maskC.getContext('2d').drawImage(ma,0,0);pC.getContext('2d').drawImage(pr,0,0);const mask=maskC.getContext('2d').getImageData(0,0,w,h),protect=pC.getContext('2d').getImageData(0,0,w,h);const finalC=createCanvas(),finalCtx=finalC.getContext('2d');const final=finalCtx.createImageData(w,h);final.data.set(before.data);let outside=0,protectedChanged=0,changed=0,rawOutside=0;const diffC=createCanvas(),diffCtx=diffC.getContext('2d'),diff=diffCtx.createImageData(w,h);for(let i=0;i<before.data.length;i+=4){const allowed=mask.data[i]>=128&&protect.data[i]<128;let rawChanged=false;for(let k=0;k<3;k++)if(raw.data[i+k]!==before.data[i+k])rawChanged=true;if(rawChanged&&mask.data[i]<128)rawOutside++;if(allowed){final.data[i]=raw.data[i];final.data[i+1]=raw.data[i+1];final.data[i+2]=raw.data[i+2]}const d=final.data[i]!==before.data[i]||final.data[i+1]!==before.data[i+1]||final.data[i+2]!==before.data[i+2];if(d){changed++;if(mask.data[i]<128)outside++;if(protect.data[i]>=128)protectedChanged++;diff.data[i]=39;diff.data[i+1]=160;diff.data[i+2]=126;diff.data[i+3]=255}else{const grey=Math.round(before.data[i]*.3+before.data[i+1]*.5+before.data[i+2]*.2);diff.data[i]=diff.data[i+1]=diff.data[i+2]=Math.round(220+grey*.13);diff.data[i+3]=255}}if(outside||protectedChanged)throw new Error('授权区域检查失败');finalCtx.putImageData(final,0,0);diffCtx.putImageData(diff,0,0);return {raw:rawC.toDataURL(),final:finalC.toDataURL(),diff:diffC.toDataURL(),finalHash:await sha(final.data),maskHash:await sha(mask.data),metrics:{changedInside:changed,changedOutside:outside,protectedChanged,rawOutside,geometryStatus:'IMAGE_ONLY',scaleStatus:'UNKNOWN',countsGuaranteedByAI:false,measurement:'decoded_rgb_pixel_comparison',rawIsModelOutput:false}}}
function renderCompare(){const tabs=$('candidateTabs');tabs.innerHTML=state.attempts.filter(a=>a.final).map(a=>`<button class="candidate-tab ${a.id===selectedCandidate?'active':''}" data-candidate="${a.id}"><img src="${a.final}" alt="候选缩略图"><div><strong>${esc(a.id)} · ${a.effect==='racks'?'机柜排布':a.effect==='clean'?'符号清理':'房名修改'}</strong><span>基于 ${esc(a.baseId)} · ${statusLabel(a.status)}</span></div></button>`).join('');tabs.querySelectorAll('[data-candidate]').forEach(el=>el.onclick=()=>{selectedCandidate=el.dataset.candidate;renderCompare()});if(!candidate()?.final){const ready=state.attempts.filter(a=>a.final).at(-1);if(ready){selectedCandidate=ready.id;renderCompare();return}$('compareContent').innerHTML=`<div class="panel empty">${icon('compare')}<h3>还没有修改候选</h3><p>先回到编辑工作台，选择一个区域并写下要求。生成的候选会放在这里，不直接覆盖当前版本。</p><button class="btn primary" id="compareBack">去涂抹一个区域 ${icon('arrow')}</button></div>`;$('compareBack').onclick=()=>setPage('editor');return}const a=candidate(),before=rev(a.baseId),stale=a.status==='ready'&&a.baseId!==state.headId;const isReady=a.status==='ready';let notification=stale?`<div class="notice-inline error">${icon('info')}来源冲突：候选基于 ${esc(a.baseId)}，当前已是 ${esc(state.headId)}。候选保留，但不能覆盖当前版本。</div>`:'';const title=a.status==='accepted'?'已保存为 '+a.acceptedRevision:a.status==='rejected'?'候选已拒绝 · 当前版本未被它改变':'待确认 · 还没有保存为版本';$('compareContent').innerHTML=notification+`<div class="compare-grid"><div><div class="panel"><div class="compare-toolbar"><div class="segmented" id="compareModes"><button data-mode="slider" class="${compareMode==='slider'?'active':''}">滑杆对比</button><button data-mode="side" class="${compareMode==='side'?'active':''}">并排</button><button data-mode="diff" class="${compareMode==='diff'?'active':''}">差异</button></div><label class="checkboxrow" style="margin:0;font-size:10px"><input type="checkbox" id="rawToggle" ${rawMode?'checked':''}>看回贴前演示图</label></div><div class="compare-stage" id="compareStage"></div><div class="compare-bottom">${icon('info')}<span>${compareMode==='diff'?'绿色显示实际变化像素；背景淡化仅用于比较，不写入版本。':rawMode?'这是程序绘制的回贴前结果，不是模型原图；可能包含保护范围内变化。':'拖动中线比较；未经批准的像素由程序复制原图保持不变。'}</span></div></div><div class="tips-card">${icon('log')}<div><strong>${esc(title)}</strong><p>${esc(a.id)} · ${niceTime(a.createdAt)} · 来源 ${esc(a.baseId)}</p></div><button class="btn ghost" data-goto="audit">查看过程 ${icon('arrow')}</button></div></div><aside><div class="panel"><div class="panel-title">${icon('shield')}候选检查</div><div class="panel-body" style="padding-top:6px"><div class="audit-row"><span>授权区外变化</span><strong class="ok">${fmt(a.metrics.changedOutside)} 像素 ${icon('check')}</strong></div><div class="audit-row"><span>保护区变化</span><strong class="ok">${fmt(a.metrics.protectedChanged)} 像素</strong></div><div class="audit-row"><span>授权区内变化</span><strong>${fmt(a.metrics.changedInside)} 像素</strong></div><div class="audit-row"><span>几何 / 尺度</span><strong class="amber-text">IMAGE_ONLY / 未知</strong></div><div class="audit-row"><span>真实模型运行</span><strong>未运行</strong></div><div class="request-quote">${esc(a.prompt)}</div><p class="prototype-note">“区外为零”是程序合成的检查结果，不代表模型能力或建筑设计已通过审查。</p><div class="compare-actions"><button class="btn danger" id="rejectCandidate" ${!isReady?'disabled':''}>拒绝候选</button><button class="btn" id="anotherCandidate" ${jobBusy||a.baseId!==state.headId?'disabled':''}>再试一个</button></div><button class="btn primary wide" style="margin-top:9px" id="acceptCandidate" ${!isReady||stale?'disabled':''}>${icon('check')}接受，保存为 r${state.revisions.length}</button>${a.status==='accepted'?`<div class="result-banner">已新增 ${esc(a.acceptedRevision)}，${esc(a.baseId)} 仍可在版本历史中恢复。</div><button class="btn wide" style="margin-top:10px" data-goto="editor">回工作台继续修改</button>`:''}${a.status==='rejected'?`<div class="result-banner danger">已拒绝：${esc(a.rejectReason||'未填写原因')}。候选和过程仍然保留。</div>`:''}${stale?'<div class="result-banner danger">需要回工作台，基于最新版本重新预览和提交。</div>':''}</div></div><button class="btn wide" id="downloadCandidate" style="margin-top:12px">${icon('download')}导出演示结果 PNG</button></aside></div>`;renderCompareImage();$('compareModes').querySelectorAll('button').forEach(el=>el.onclick=()=>{compareMode=el.dataset.mode;renderCompare()});$('rawToggle').onchange=()=>{rawMode=$('rawToggle').checked;renderCompare()};$('acceptCandidate').onclick=acceptCandidate;$('rejectCandidate').onclick=rejectCandidate;$('anotherCandidate').onclick=()=>{generate({baseId:a.baseId,prompt:a.prompt,effect:a.effect,settings:a.settings,strokes:a.strokes,mask:a.mask,protection:a.protection,stats:a.stats})};$('downloadCandidate').onclick=()=>downloadData(a.final,`P2_${a.id}_演示候选.png`);bindGoto($('compareContent'))}
function statusLabel(s){return ({ready:'待确认',accepted:'已接受',rejected:'已拒绝',cancelled:'已取消',running:'演示处理中',failed:'失败'})[s]||s}
function renderCompareImage(){const a=candidate(),before=rev(a.baseId),after=rawMode?a.raw:a.final;const stage=$('compareStage');if(compareMode==='side'){stage.innerHTML=`<div class="sidebyside"><figure><img src="${before.image}" alt="修改前"><span class="image-label">修改前 · ${esc(before.id)}</span></figure><figure><img src="${after}" alt="修改后演示候选"><span class="image-label right">${rawMode?'回贴前':'候选'} · ${esc(a.id)}</span></figure></div>`}else if(compareMode==='diff'){stage.innerHTML=`<div class="compare-single"><img src="${a.diff}" alt="差异热图"><span class="image-label">最终候选的变化区域</span></div>`}else{stage.innerHTML=`<div class="compare-single"><img src="${before.image}" alt="原始版本"><div class="afterclip" id="afterClip"><img src="${after}" alt="演示候选"></div><span class="image-label">修改前 · ${esc(before.id)}</span><span class="image-label right">${rawMode?'回贴前演示':'最终候选'} · ${esc(a.id)}</span><div class="divider" id="divider"></div><input class="compare-range" id="compareSlider" type="range" min="0" max="100" value="28" aria-label="拖动比较修改前后"></div>`;$('compareSlider').oninput=()=>{const val=$('compareSlider').value;$('afterClip').style.clipPath=`inset(0 0 0 ${val}%)`;$('divider').style.left=val+'%'}}}
async function acceptCandidate(){const a=candidate();if(!a||a.status!=='ready')return;if(a.baseId!==state.headId){addEvent('candidate.conflict','拒绝过期候选覆盖当前版本',{candidate:a.id,base:a.baseId,current:state.headId},'decision');toast('版本冲突，当前版本已变化',true);renderCompare();return}if(state.revisions.length>=LIMITS.revisions){toast('演示已达到 24 个版本，请先导出工程并重置',true);return}const id='r'+state.revisions.length;const next={id,parent:state.headId,restoreFrom:null,time:now(),type:'edit',title:a.effect==='racks'?'调整机柜排布':a.effect==='clean'?'清理选区符号':'修改房名',description:a.prompt,image:a.final,imageHash:a.finalHash,candidateId:a.id,geometryStatus:'IMAGE_ONLY'};state.revisions.push(next);state.headId=id;a.status='accepted';a.acceptedRevision=id;selectedRevision=id;addEvent('candidate.accepted','接受候选，创建新版本',{candidate:a.id,revision:id,parent:next.parent,geometry_status:'IMAGE_ONLY',scale_status:'UNKNOWN',p3_handoff:false},'decision');state.draft.commands=[];state.draft.redo=[];$('prompt').value='';updatePromptCount();currentImage=await imageOf(next.image);lastLoadedHead=id;rebuildMasks();updateChrome();renderCompare();banner(`已保存 ${id}。上一版本 ${next.parent} 保留，可在版本历史中恢复。`);scheduleSave();toast(`已保存 ${id}，旧版本没有被覆盖`)}
